    // Shared memory for tiles
    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];

    int bx = blockIdx.x;
    int by = blockIdx.y;
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Row and column of the C element to compute
    int row = by * TILE_SIZE + ty;
    int col = bx * TILE_SIZE + tx;

    float sum = 0.0f;

    // Loop over tiles with unrolling
    int num_tiles = (N + TILE_SIZE - 1) / TILE_SIZE;
    for (int t = 0; t < num_tiles; t += UNROLL_FACTOR) {
        // Precompute indices for unrolled loading
        int A_col[UNROLL_FACTOR], B_row[UNROLL_FACTOR];
        for (int u = 0; u < UNROLL_FACTOR; u++) {
            if (t + u < num_tiles) {
                A_col[u] = (t + u) * TILE_SIZE + tx;
                B_row[u] = (t + u) * TILE_SIZE + ty;
            }
        }

        // Load unrolled tiles into shared memory
        for (int u = 0; u < UNROLL_FACTOR; u++) {
            if (t + u < num_tiles) {
                // Load tile from A
                if (row < N && A_col[u] < N) {
                    As[ty][tx] = A[row * N + A_col[u]];
                } else {
                    As[ty][tx] = 0.0f;
