#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_SIZE 16

// Define float4 for vectorized memory access
struct float4 { float x, y, z, w; };

__global__ void matrix_mul_kernel(const float* A, const float* B, float* C, int N) {
    // Shared memory for tiles
    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];

    int bx = blockIdx.x;
    int by = blockIdx.y;
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Row and column of the C element to compute
    int row = by * TILE_SIZE + ty;
    int col = bx * TILE_SIZE + tx;

    float sum = 0.0f;

    // Loop over tiles
    for (int t = 0; t < (N + TILE_SIZE - 1) / TILE_SIZE; t++) {
        // Vectorized load for tile A
        int A_index = row * N + t * TILE_SIZE + tx;
        if (row < N && t * TILE_SIZE + tx < N) {
            // Load 4 elements at once
            float4 A_vec = *reinterpret_cast<const float4*>(&A[A_index]);
            As[ty][tx] = A_vec.x;
            if (tx + TILE_SIZE < N) {
                As[ty][tx + TILE_SIZE] = A_vec.y;
                As[ty][tx + 2*TILE_SIZE] = A_vec.z;
                As[ty][tx + 3*TILE_SIZE] = A_vec.w;
            }
        } else {
            As[ty][tx] = 0.0f;
        }

        // Vectorized load for tile B
        int B_index = (t * TILE_SIZE + ty) * N + col;
        if (t * TILE_SIZE + ty < N && col < N) {
            // Load 4 elements at once
            float4 B_vec = *reinterpret_cast<const float4*>(&B[B_index]);
            Bs[ty][tx] = B_vec.x;
            if (ty + TILE_SIZE < N) {
                Bs[ty + TILE_SIZE][tx] = B_vec.y;
                Bs[ty + 2*TILE_SIZE][tx] = B_vec.z;
                Bs[ty + 3*TILE_SIZE][tx] = B_vec.w;
